import{createCrescentTerrain,CRESCENT_DEFAULT_DIMENSIONS}from'../../src/terrain/crescent.ts';
import{PolyhedronDisplayCache}from'../../src/rendering/polyhedron-field.ts';
import{CrescentPresentation}from'../../src/rendering/crescent-presentation.ts';
import{initialCrescentView}from'../../src/rendering/crescent-view.ts';
import{pyramidCross,pyramidUnit}from'../../src/surfaces/pyramid.ts';
export async function crescentRenderPilot(){
 const t=createCrescentTerrain({terrainId:'heights',detail:128,geometry:{...CRESCENT_DEFAULT_DIMENSIONS,identity:{worldId:'crescent',surfaceId:'boundary'},provider:'physical-prismatic-crescent',version:1,role:'exterior'}}),g=t.geometry;
 for(let i=0;i<t.sampleCount;i++){const k=t.keyAt(i),p=t.referencePositionAt(k);t.write(k,Math.fround(900*(p[0]/g.scaleMeters+.35*p[2]/g.scaleMeters-.5)));}
 const started=performance.now(),cache=new PolyhedronDisplayCache(t);let last=performance.now();for(const _ of cache.prepare()){if(performance.now()-last>5){await new Promise(resolve=>setTimeout(resolve,0));last=performance.now();}}const preparationMs=performance.now()-started;
 const root=document.createElement('main');root.style.cssText='display:grid;grid-template-columns:640px 640px;gap:16px';document.querySelector('#root')!.setAttribute('style','display:none');document.body.append(root);document.body.style.cssText='background:#071924;margin:16px;color:white';const results=[];
 for(const pose of['top','oblique','underside','map']as const){const gpu=document.createElement('canvas'),cpu=document.createElement('canvas');for(const c of[gpu,cpu]){c.style.cssText='width:640px;height:480px;background:#0b1821';root.append(c);}const presenter=new CrescentPresentation(gpu,cpu,cache,()=>{});let view=initialCrescentView(pose==='map'?'map':'physical');if(pose==='top'||pose==='underside'){const forward=pyramidUnit([0,pose==='top'?1:-1,0]),right=pyramidUnit([1,0,0]);view={...view,frame:{forward,right,up:pyramidCross(forward,right)}};}presenter.present(view,{width:640,height:480},'relief');if(presenter.backend!=='webgl2')throw Error(presenter.statistics.reason);const gl=gpu.getContext('webgl2')!,raw=new Uint8Array(gpu.width*gpu.height*4);gl.readPixels(0,0,gpu.width,gpu.height,gl.RGBA,gl.UNSIGNED_BYTE,raw);const output=new Uint8ClampedArray(raw.length);for(let y=0;y<gpu.height;y++)output.set(raw.subarray((gpu.height-y-1)*gpu.width*4,(gpu.height-y)*gpu.width*4),y*gpu.width*4);const statistics={...presenter.statistics};presenter.fail('Forced Canvas pilot');presenter.present(view,{width:640,height:480},'relief');const canvas=cpu.getContext('2d')!.getImageData(0,0,cpu.width,cpu.height).data;let checked=0,stableMax=0,opaqueMismatch=0;
  for(let y=3;y<cpu.height-3;y+=2)for(let x=3;x<cpu.width-3;x+=2){const at=(y*cpu.width+x)*4;if(output[at+3]!==255||canvas[at+3]!==255)continue;let stable=true;for(const dy of[-2,0,2])for(const dx of[-2,0,2]){const i=((y+dy)*cpu.width+x+dx)*4;if(output[i+3]!==255||canvas[i+3]!==255||Math.abs(output[i]!-output[at]!)>4||Math.abs(output[i+1]!-output[at+1]!)>4||Math.abs(output[i+2]!-output[at+2]!)>4)stable=false;}if(stable){checked++;for(let c=0;c<3;c++)stableMax=Math.max(stableMax,Math.abs(output[at+c]!-canvas[at+c]!));}if(output[at+3]!==canvas[at+3])opaqueMismatch++;}
  const frozen=document.createElement('canvas');frozen.width=gpu.width;frozen.height=gpu.height;frozen.style.cssText=gpu.style.cssText;frozen.getContext('2d')!.putImageData(new ImageData(output,gpu.width,gpu.height),0,0);gpu.replaceWith(frozen);presenter.dispose();results.push({pose,statistics,checked,stableMax,opaqueMismatch});
 }
 return{preparationMs,cacheBytes:cache.ownedArrayBufferBytes,results};
}
